automaSetVariable('seenIds', '0,');
automaSetVariable('currentId', '');
automaSetVariable('currentTitle', '');
automaSetVariable('currentDescription', '');
automaSetVariable('applyUrl', '');
automaSetVariable('isDuplicate', 'false');
automaSetVariable('insertCount', '0');
automaSetVariable('cardFound', 'false');
automaSetVariable('hasRows', 'false');
automaNextBlock();

(async () => {
  let finished = false;
  const finish = () => { if (!finished) { finished = true; automaNextBlock(); } };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const findText = (regex) => {
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.children.length === 0 && regex.test((node.textContent || '').trim())) return node;
    }
    return null;
  };
  const clickClosest = (el) => {
    const target = el.closest('button') || el.closest('[role="button"]') || el.closest('a') || el.closest('label') || el;
    target.click();
  };
  try {
    const ACCEPT_RE = /accept tracking and continue|zustimmen und fortfahren|alle akzeptieren|alles akzeptieren|accept all|zustimmen/i;
    const accept = findText(ACCEPT_RE);
    if (accept) { clickClosest(accept); await sleep(1500); }
    if (location.href.indexOf('sincePeriod=LAST_WEEK') !== -1) { finish(); return; }
    const OPTION_RE = /last week|letzte 7 tage|past 7 days|letzten 7 tage/i;
    const HEADER_RE = /date posted|ver\u00f6ffentlichungsdatum/i;
    let option = findText(OPTION_RE);
    if (!option) {
      const header = findText(HEADER_RE);
      if (header) { clickClosest(header); await sleep(800); option = findText(OPTION_RE); }
    }
    if (option) { clickClosest(option); await sleep(1000); }
    finish();
  } catch (e) { finish(); }
})();

(() => {
  let finished = false;
  const finish = () => { if (!finished) { finished = true; automaNextBlock(); } };
  const hrefOk = (href) => /\/jobs\/[a-z0-9-]+-\d+$/.test(href) && href.indexOf('/jobs/search') === -1 && href.indexOf('/jobs/create') === -1;
  try {
    const card = Array.from(document.querySelectorAll('a[href]')).find((a) => {
      const href = (a.href || a.getAttribute('href') || '').split('#')[0].split('?')[0];
      if (!hrefOk(href)) return false;
      if (a.hasAttribute('data-job-list-item')) return false;
      return true;
    });
    if (card) {
      card.setAttribute('data-job-list-item', 'active');
      let href = card.href || card.getAttribute('href') || '';
      href = href.split('#')[0].split('?')[0];
      if (!/^https?:/.test(href)) href = new URL(href, location.href).href;
      const m = href.match(/-(\d+)$/);
      automaSetVariable('applyUrl', href);
      automaSetVariable('currentId', m ? m[1] : '');
      const heading = card.querySelector('h1, h2, h3, h4, h5, h6') || card;
      automaSetVariable('currentTitle', (heading.textContent || '').replace(/\s+/g, ' ').trim());
      automaSetVariable('cardFound', 'true');
    } else {
      automaSetVariable('cardFound', 'false');
    }
    finish();
  } catch (e) { automaSetVariable('cardFound', 'false'); finish(); }
})();

(async () => {
  let finished = false;
  const finish = () => { if (!finished) { finished = true; automaNextBlock(); } };
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const collapse = (s) => s.replace(/\s+/g, ' ').trim();
  const stripHtml = (s) => {
    const div = document.createElement('div');
    div.innerHTML = s;
    return div.textContent || '';
  };
  const findPosting = (obj) => {
    if (!obj || typeof obj !== 'object') return null;
    if (Array.isArray(obj)) {
      for (const item of obj) {
        const hit = findPosting(item);
        if (hit) return hit;
      }
      return null;
    }
    const types = Array.isArray(obj['@type']) ? obj['@type'] : [obj['@type']];
    if (types.some((t) => typeof t === 'string' && t.indexOf('JobPosting') !== -1)) return obj;
    for (const key of Object.keys(obj)) {
      if (key === '@context') continue;
      const hit = findPosting(obj[key]);
      if (hit) return hit;
    }
    return null;
  };
  const fromLdJson = () => {
    const scripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]'));
    for (const script of scripts) {
      let parsed;
      try { parsed = JSON.parse(script.textContent || ''); } catch (e) { continue; }
      const posting = findPosting(parsed);
      if (posting && typeof posting.description === 'string' && posting.description.trim()) return posting.description;
    }
    return '';
  };
  const fromExpandable = () => {
    const el = document.querySelector('div[data-testid="expandable-content"]');
    return el ? (el.innerText || el.textContent || '') : '';
  };
  const fromMeta = () => {
    const m = document.querySelector('meta[name="description"]');
    const content = m ? (m.content || m.getAttribute('content') || '') : '';
    if (!content) return '';
    const sentenceCount = (content.match(/[.!?]+/g) || []).length;
    if (content.length < 100 || sentenceCount < 2) return '';
    return content;
  };
  const extract = () => fromLdJson() || fromExpandable() || fromMeta();
  try {
    const seen = automaRefData('variables', 'seenIds') || '0,';
    const id = automaRefData('variables', 'currentId') || '';
    automaSetVariable('extractionError', '');
    let raw = extract();
    if (!raw) {
      for (let i = 0; i < 5; i++) {
        await sleep(700);
        raw = extract();
        if (raw) break;
      }
    }
    const desc = collapse(stripHtml(raw));
    const dup = id ? seen.indexOf(id + ',') >= 0 : false;
    const empty = !desc;
    automaSetVariable('currentDescription', desc.slice(0, 8000));
    automaSetVariable('isDuplicate', dup || empty ? 'true' : 'false');
    if (!dup && !empty && id) automaSetVariable('seenIds', seen + id + ',');
    finish();
  } catch (e) {
    automaSetVariable('extractionError', String(e && e.message ? e.message : e));
    automaSetVariable('currentDescription', '');
    automaSetVariable('isDuplicate', 'true');
    finish();
  }
})();

const n = Number(automaRefData('variables', 'insertCount') || 0);
automaSetVariable('hasRows', n > 0 ? 'true' : 'false');
automaNextBlock();
